mapper.select:
SELECT pair_id, senior_student_id, senior_student_name, junior_student_id, junior_student_name, dance_class_name AS term_name, star_points, checkin_count, created_at
FROM student_mentorship
WHERE pair_id = #{pairId}

mapper.update:
UPDATE student_mentorship
SET star_points = star_points + #{addStars}, checkin_count = checkin_count + 1
WHERE pair_id = #{pairId}

mapper.insert:
INSERT INTO student_mentorship (
    pair_id, senior_student_id, senior_student_name, junior_student_id, junior_student_name, dance_class_name, star_points, checkin_count
) VALUES (
    #{pairId}, #{seniorStudentId}, #{seniorStudentName}, #{juniorStudentId}, #{juniorStudentName}, #{termName}, #{starPoints}, #{checkinCount}
)
